-- ═══ Memahami Ekosistem Web Modern & AI ═══
INSERT OR IGNORE INTO courses (id, slug, title, subtitle, short_description, description, thumbnail_url, level, category, instructor_name, access_type, price, status, sort_order, published_at, created_at, updated_at) VALUES ('eb1f34a9-4159-4cd4-adcc-ede956e53803', 'memahami-ekosistem-web-modern-ai', 'Memahami Ekosistem Web Modern & AI', 'Fondasi wajib sebelum membangun website dengan bantuan AI', 'Pahami ekosistem web modern dari nol: peran AI dalam pembuatan website, static website, tools seperti GitHub, Netlify, Cloudflare Pages, dan dasar-dasar Framer.', 'Kelas pembuka seri Vibecoding untuk pemula. Kamu akan memahami bagaimana AI mengubah cara website dibuat, bedanya website tradisional dengan static website modern, dan peta tools yang akan dipakai sepanjang perjalanan: AI generator, GitHub, Netlify, Cloudflare Pages, dan Framer. Di akhir kelas kamu sudah menyiapkan semua akun yang dibutuhkan dan paham anatomi project Framer, interface builder, serta cara kerja layer - fondasi yang bikin kelas berikutnya terasa mudah.', 'https://pub-d56d873c4b8d4204b35361d7bea0dca8.r2.dev/Kelas/Kelas%20Vibecoding%20Beginner.webp', 'beginner', 'Gratis', 'Pejuang Yen Team', 'free', 0, 'published', 10, '2026-06-10T08:00:00.000Z', '2026-06-10T08:00:00.000Z', '2026-06-10T08:00:00.000Z');
