-- ═══ Integrasi GitHub sebagai Jantung Website ═══
INSERT OR IGNORE INTO courses (id, slug, title, subtitle, short_description, description, thumbnail_url, level, category, instructor_name, access_type, price, status, sort_order, published_at, created_at, updated_at) VALUES ('3dc84a6c-c8ec-4fb3-af1e-39527900dd28', 'integrasi-github-jantung-website', 'Integrasi GitHub sebagai Jantung Website', 'Kuasai GitHub sebagai pusat kendali source code website-mu', 'Belajar GitHub dari nol: kenapa wajib dikuasai, membuat repository pertama, dan upload file source code sebagai pondasi deployment website.', 'GitHub adalah jantung dari workflow website modern - tempat semua source code hidup sebelum di-deploy ke Netlify atau Cloudflare Pages. Di kelas singkat ini kamu akan paham konsep GitHub tanpa jargon, langsung praktik membuat repository pertama, dan meng-upload file website ke dalamnya. Setelah kelas ini, alur kode dari AI generator menuju website live tidak lagi terasa misterius.', 'https://pub-d56d873c4b8d4204b35361d7bea0dca8.r2.dev/Kelas/Kelas%20Vibecoding%20Beginner.webp', 'beginner', 'Gratis', 'Pejuang Yen Team', 'free', 0, 'published', 11, '2026-06-10T08:00:00.000Z', '2026-06-10T08:00:00.000Z', '2026-06-10T08:00:00.000Z');
