-- ═══ Membuat Website & Landing Page dengan Bantuan AI ═══
INSERT OR IGNORE INTO courses (id, slug, title, subtitle, short_description, description, thumbnail_url, level, category, instructor_name, access_type, price, status, sort_order, published_at, created_at, updated_at) VALUES ('3a488c93-7627-416d-aac0-23f6bf3e5858', 'membuat-website-landing-page-dengan-ai', 'Membuat Website & Landing Page dengan Bantuan AI', 'Dari prompt ke website live: bangun landing page high-converting dengan AI dan Framer', 'Praktik penuh membangun website dengan AI: prompt engineering untuk UI/UX, landing page high-converting, website multi-halaman, debugging, sampai siap deploy.', 'Kelas praktik inti dari seri Vibecoding. Kamu akan menguasai prompt engineering khusus UI/UX, lalu memakai AI untuk membangun landing page high-converting dan website multi-halaman. Kami bahas juga skill yang jarang diajarkan: troubleshooting dan debugging dengan AI, serta menyiapkan source code agar siap deploy. Di sisi Framer, kamu belajar menambahkan gambar, video, dan teks, memakai Insert Panel, import desain dari Figma, generate layout otomatis dengan AI Wireframer, hingga mengatur link antarhalaman.', 'https://pub-d56d873c4b8d4204b35361d7bea0dca8.r2.dev/Kelas/Kelas%20Vibecoding%20Beginner.webp', 'beginner', 'Gratis', 'Pejuang Yen Team', 'free', 0, 'published', 12, '2026-06-10T08:00:00.000Z', '2026-06-10T08:00:00.000Z', '2026-06-10T08:00:00.000Z');
